 using System.Drawing.Design;
 using System.Runtime.InteropServices;
 using System.Windows.Forms;
 using System.Windows.Forms.Design;

 public class MyControl : UserControl
 {
     private StatusStrip _statusStrip;

     public string DisplayName { get; set; }
     public int MaxItems { get; set; }

     public MyControl()
     {
         _statusStrip = new StatusStrip();
         // .NET 9 breaking change: default renderer changed for StatusStrip.
         // Explicitly set to System to preserve .NET 8 appearance.
         _statusStrip.RenderMode = ToolStripRenderMode.System;
         Controls.Add(_statusStrip);
     }

     /// <summary>
     /// Safely calls DropDownControl with a null guard.
     /// In .NET 9, passing null throws ArgumentNullException.
     /// </summary>
     public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
     {
         if (control is null)
             return;

         editorService.DropDownControl(control);
     }

     // .NET 9: Use LibraryImport (source-generated) instead of DllImport for
     // better performance and AOT compatibility.
     [LibraryImport("user32.dll", SetLastError = true)]
     [return: MarshalAs(UnmanagedType.Bool)]
     private static partial bool SetForegroundWindow(nint hWnd);
 }
